def search_range(nums, target):
    def first_at_least(x):
        """Index of the first element >= x, or len(nums) if there is none."""
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < x:
                lo = mid + 1                  # nums[mid] and everything before it is too small
            else:
                hi = mid                      # mid could be the answer, so keep it
        return lo

    first = first_at_least(target)
    if first == len(nums) or nums[first] != target:
        return [-1, -1]
    return [first, first_at_least(target + 1) - 1]
